import{_ as r,C as n,o as s,c as i,j as t,a as o,G as l,a2 as p}from"./chunks/framework.BgSoyxN5.js";const f=JSON.parse('{"title":"TickerForge Partner Cabinet | How Approved Partners Create Posts in Telegram","description":"How the TickerForge Partner Cabinet works: who gets access, which partner posts are created there, how tracked links and statistics work, and what generated versus published means.","frontmatter":{"title":"TickerForge Partner Cabinet | How Approved Partners Create Posts in Telegram","description":"How the TickerForge Partner Cabinet works: who gets access, which partner posts are created there, how tracked links and statistics work, and what generated versus published means.","aside":false,"locale":"en","alternateLocales":{"en":"/partners/cabinet","ru":"/ru/partners/cabinet"},"pageClass":"partners-page"},"headers":[],"relativePath":"partners/cabinet.md","filePath":"partners/cabinet.md","lastUpdated":1788362384000}'),d={name:"partners/cabinet.md"};function c(h,e,u,g,m,b){const a=n("PartnerPageAnalytics");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"how-partner-cabinet-works",tabindex:"-1"},[o("How Partner Cabinet Works "),t("a",{class:"header-anchor",href:"#how-partner-cabinet-works","aria-label":'Permalink to "How Partner Cabinet Works"'},"​")],-1)),e[1]||(e[1]=t("p",null,"The Partner Cabinet is where an approved partner actually creates partner posts. It lives inside Telegram, not on this website.",-1)),l(a,{offer:"cabinet",locale:"en"}),e[2]||(e[2]=p('<p class="partners-locale-switch"><a href="/ru/partners/cabinet" hreflang="ru" data-partner-event="cta" data-partner-option="locale_ru" data-analytics-placement="partner_locale_switch">Читать эту страницу на русском</a></p><p class="partners-backlink"><a href="/partners">Back to all partner options</a> · <a href="/partners/stock-analysis-and-ideas">Telegram research</a> · <a href="/partners/market-news">Market news</a> · <a href="/partners/portfolio-health">Portfolio health</a> · <a href="/partners/requirements">Partner requirements</a></p><h2 id="getting-in" tabindex="-1">Getting In <a class="header-anchor" href="#getting-in" aria-label="Permalink to &quot;Getting In&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Approval first.</strong> Sending the partner form creates a lead. Nothing is granted until a person reviews it — see the <a href="/partners/requirements#lifecycle">status lifecycle</a>.</li><li><strong>Open <code>/partners</code> in Telegram.</strong> The same command shows the public program hub to everyone and the Cabinet to approved partners.</li><li><strong>Access is keyed to your Telegram account.</strong> The approved account is what opens the Cabinet. A partner code typed by somebody else grants nothing, and access is not transferable.</li><li><strong>Access is time-limited.</strong> When the pilot window ends or is paused, the Cabinet closes and posts can no longer be generated.</li></ul></div><h2 id="creating-a-partner-post" tabindex="-1">Creating A Partner Post <a class="header-anchor" href="#creating-a-partner-post" aria-label="Permalink to &quot;Creating A Partner Post&quot;">​</a></h2><p>Approved partners create supported partner posts in the Telegram Partner Cabinet. &quot;Supported&quot; is the important word: the Cabinet generates the formats that have a working generator behind them today, while other formats on the program pages are prepared with us as part of a pilot.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Company research posts.</strong> You enter a ticker and receive a ready-to-share post: Stock Verdict, Insider Activity, Fund Moves.</li><li><strong>Stock idea posts.</strong> Turnaround and Insiders Are Buying can use the current qualifying pick or validate a ticker you enter, using the same rule as the channel post.</li><li><strong>Market post.</strong> A market update built from the current weekly Market Regime view. No ticker needed.</li><li><strong>Everything else on the program pages</strong> is requestable: tell us in the form which format matters, and partner demand decides what becomes self-service next.</li></ul></div><h2 id="tracked-links" tabindex="-1">Tracked Links <a class="header-anchor" href="#tracked-links" aria-label="Permalink to &quot;Tracked Links&quot;">​</a></h2><p>Every generated post carries your own tracked link. The public link is short and opaque — it does not encode your partner code, the month, the rubric, the workflow, or the ticker. Those stay in TickerForge as reporting fields.</p><p>Readers who follow the link land in the matching TickerForge workflow, and the existing referral rules decide attribution. First touch wins: a reader who already belongs to another ambassador is not re-attributed.</p><h2 id="statistics-and-reporting" tabindex="-1">Statistics And Reporting <a class="header-anchor" href="#statistics-and-reporting" aria-label="Permalink to &quot;Statistics And Reporting&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Statistics:</strong> tracked clicks, referrals, current-month paid referrals, and a compact breakdown by post type.</li><li><strong>Monthly report:</strong> current or previous month as an XLSX with Summary and Posts sheets.</li><li><strong>Raw clicks</strong> are link hits, not unique people.</li><li><strong>Bot starts</strong> are unique Telegram users whose first partner-post start came from that post.</li><li><strong>Paid subscriptions</strong> are a current snapshot of active paid plans among your referrals, not a historical payment ledger.</li></ul></div><h2 id="generated-is-not-published" tabindex="-1">Generated Is Not Published <a class="header-anchor" href="#generated-is-not-published" aria-label="Permalink to &quot;Generated Is Not Published&quot;">​</a></h2><div class="partners-wide partners-routing-note"><p><strong>Generating a post in the Cabinet does not count as a publication.</strong> The Cabinet shows generated posts and verified posts separately, and only published posts we can verify count toward the posting requirement in your pilot.</p><a class="partners-button partners-button--secondary" href="/partners/requirements#commitments">Read the posting commitments</a></div><h2 id="what-the-cabinet-is-not" tabindex="-1">What The Cabinet Is Not <a class="header-anchor" href="#what-the-cabinet-is-not" aria-label="Permalink to &quot;What The Cabinet Is Not&quot;">​</a></h2><div class="partners-wide partners-wide--not"><p>The Partner Cabinet does not:</p><ul><li>publish to your channel for you</li><li>grant access to anyone you forward a link to</li><li>generate every format listed on the program pages</li><li>replace your own analysis, disclaimer, or editorial judgement</li></ul></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/partners">All partner options</a></li><li><a href="/partners/requirements">Partner requirements</a></li><li><a href="/partners/stock-analysis-and-ideas">Telegram research partners</a></li><li><a href="/partners/market-news">Market news partners</a></li><li><a href="/partners/portfolio-health">Portfolio health partners</a></li><li><a href="/ambassador">Ambassador / referral program</a></li></ul>',18))])}const k=r(d,[["render",c]]);export{f as __pageData,k as default};
